<template>
  <view :class="['page issue-policy-page', darkMode ? 'dark-mode' : '', `font-${fontSize}`]">
    <view class="settings-nav ip-nav"><button class="back-button" aria-label="返回" @click="back"><text class="back-symbol"></text></button></view><text v-if="loading" class="ip-muted" role="status">正在核对政策版本…</text><text v-if="error" class="ip-error" role="alert">{{ error }}</text><button v-if="error" class="ip-button" @click="load">重新加载当前政策</button>
    <template v-if="policy"><text class="ip-muted">{{ policy.region }}</text><text class="ip-heading">{{ policy.title }}</text><text class="ip-body">{{ policy.summary }}</text><text class="ip-muted">核验时间：{{ policy.verified_at || '未核验' }} · 复核期限：{{ policy.review_expires_at || '未设置' }}</text><text class="ip-muted">匿名自查；答案仅在本页内存中，离开后清除。结果供准备申请参考，以官方审核为准。</text>
      <view v-if="unavailable" class="ip-card"><text class="ip-title">暂不可自查</text><text class="ip-body">{{ policy.unavailable_reason || '政策已暂停或超过复核期限，请查看官方依据。' }}</text></view>
      <view v-else-if="!result && question" class="ip-card"><text class="ip-muted ip-count">第 {{ step + 1 }} / {{ policy.questions.length }} 题</text><text class="ip-title">{{ question.title }}</text><text class="ip-muted">{{ question.help }}</text><button v-for="option in question.options" :key="option.value" :class="['ip-option', answers[question.id] === option.value ? 'chosen' : '']" :aria-pressed="answers[question.id] === option.value" @click="choose(option.value)">{{ answers[question.id] === option.value ? '✓ ' : '' }}{{ option.label }}</button><view class="ip-actions"><button class="ip-button" :disabled="step === 0 || busy" @click="step--">上一题</button><button v-if="step < policy.questions.length - 1" class="ip-button primary" :disabled="!answered || busy" @click="step++">下一题</button><button v-else class="ip-button primary" :disabled="!answered || busy" @click="evaluate">{{ busy ? '正在核对…' : '查看自查结果' }}</button></view></view>
      <view v-if="result" class="ip-card" aria-live="polite"><text class="ip-title">{{ labels[result.result] }}</text><text class="ip-body">{{ result.title }}</text><view v-for="check in result.checks" :key="check.question_id" class="ip-card"><text class="ip-title">{{ check.title }} · {{ checkLabels[check.status] }}</text><text class="ip-body">{{ check.reason }}</text><button v-if="sourceFor(check.source_id)" class="ip-button" @click="official(sourceFor(check.source_id).url)">查看此项官方依据</button></view><text v-for="(item, i) in result.next_steps || []" :key="i" class="ip-body">{{ item }}</text></view>
      <view class="ip-actions"><button v-if="!unavailable" class="ip-button" :disabled="busy" @click="reset">{{ result ? '重新自查' : '清空答案' }}</button><button class="ip-button" @click="ask">问问这项政策</button></view>
      <view class="ip-card"><text class="ip-title">官方依据</text><button v-for="source in sources" :key="source.id" class="ip-button" @click="official(source.url)">{{ source.title }} · {{ source.org }} {{ source.published_at || '' }}</button></view>
      <view v-if="materials.length" class="ip-card"><text class="ip-title">申请材料</text><text v-for="(item, i) in materials" :key="i" class="ip-body">{{ item }}</text></view><button v-if="applicationUrl" class="ip-button primary" @click="official(applicationUrl)">前往官方办理入口</button>
    </template>
  </view>
</template>
<script>
import { getPolicyCheck, evaluatePolicyCheck } from '@/utils/api.js'
import { pendingQuestion, openOfficialUrl, resultLabels, checkLabels, policyUnavailable } from '@/utils/issue-policy.js'
export default {
  data: () => ({ key: '', policy: null, answers: {}, result: null, step: 0, loading: false, busy: false, error: '', darkMode: false, fontSize: 'standard', generation: 0, labels: resultLabels, checkLabels }),
  computed: { unavailable() { return this.policy && policyUnavailable(this.policy) }, question() { return this.policy?.questions?.[this.step] }, answered() { return this.question && this.answers[this.question.id] !== undefined }, sources() { return this.result?.sources || this.policy?.sources || [] }, materials() { return this.result?.materials || this.policy?.materials || [] }, applicationUrl() { return this.result?.application_url || this.policy?.application_url || '' } },
  onLoad(options) { this.key = options.key || '' }, onShow() { this.darkMode = !!uni.getStorageSync('jianwen_dark_mode'); this.fontSize = uni.getStorageSync('jianwen_font_size') || 'standard'; this.load() },
  onHide() { this.generation++; this.answers = {}; this.result = null; this.policy = null }, onUnload() { this.generation++; this.answers = {}; this.result = null },
  methods: { official: openOfficialUrl, back() { const fallback = () => uni.redirectTo({ url: '/pages/policy/index' }); if (getCurrentPages().length > 1) uni.navigateBack({ fail: fallback }); else fallback() }, sourceFor(id) { return this.sources.find(s => s.id === id) }, choose(value) { this.answers[this.question.id] = value }, reset() { this.answers = {}; this.result = null; this.step = 0; this.error = '' }, ask() { pendingQuestion('policy', this.key, this.policy.title) },
    async load() { const generation = ++this.generation; this.reset(); this.loading = true; try { const data = await getPolicyCheck(this.key); if (generation === this.generation) this.policy = data } catch (e) { if (generation === this.generation) this.error = e.message } finally { if (generation === this.generation) this.loading = false } },
    async evaluate() { if (this.busy || this.unavailable) return; this.busy = true; this.error = ''; const generation = this.generation; try { const data = await evaluatePolicyCheck(this.key, this.policy.version, this.answers); if (generation === this.generation) this.result = data } catch (e) { if (generation !== this.generation) return; if ([409, 410].includes(e.status)) { this.answers = {}; this.result = null; this.policy = null; this.error = e.status === 409 ? '政策版本已更新，请重新加载后再自查。' : '政策已暂停或到期，请重新加载查看官方依据。' } else this.error = e.message } finally { this.busy = false } }
  }
}
</script>
<style src="../../styles/issue-policy.css"></style>
